CREATE TRIGGER sync_cabinet_shared AFTER UPDATE OF synced ON cabinets
  WHEN OLD.synced = 0
    AND NEW.synced = 1
    AND NOT EXISTS (SELECT 1 FROM sync_meta WHERE key = 'applying')
BEGIN
  INSERT INTO outbox (id, entity, entity_id, cabinet_id, op, payload, edited_at)
    VALUES (lower(hex(randomblob(16))), 'cabinets', NEW.id, NEW.id, 'insert', json_object('name', json(json_quote(NEW.name)), 'place', json(json_quote(NEW.place)), 'icon', json(json_quote(NEW.icon)), 'mode', json(json_quote(NEW.mode)), 'expiry_warning_days', json(json_quote(NEW.expiry_warning_days)), 'created_at', json(json_quote(NEW.created_at))), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
  INSERT INTO outbox (id, entity, entity_id, cabinet_id, op, payload, edited_at)
    SELECT lower(hex(randomblob(16))), 'medicines', m.id, m.cabinet_id, 'insert', json_object('cabinet_id', json(json_quote(m.cabinet_id)), 'name', json(json_quote(m.name)), 'inn', json(json_quote(m.inn)), 'form', json(json_quote(m.form)), 'strength', json(json_quote(m.strength)), 'manufacturer', json(json_quote(m.manufacturer)), 'rx', json(CASE WHEN m.rx THEN 'true' ELSE 'false' END), 'low_stock_threshold', json(json_quote(m.low_stock_threshold)), 'register_id', json(json_quote(m.register_id)), 'created_at', json(json_quote(m.created_at))), strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
    FROM medicines m WHERE m.cabinet_id = NEW.id ORDER BY m.created_at;
  INSERT INTO outbox (id, entity, entity_id, cabinet_id, op, payload, edited_at)
    SELECT lower(hex(randomblob(16))), 'custom_categories', c.id, NULL, 'insert', json_object('name', json(json_quote(c.name)), 'icon', json(json_quote(c.icon)), 'created_at', json(json_quote(c.created_at))), strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
    FROM custom_categories c WHERE c.id IN (
      SELECT mc.category FROM medicine_categories mc JOIN medicines m ON m.id = mc.medicine_id WHERE m.cabinet_id = NEW.id);
  INSERT INTO outbox (id, entity, entity_id, cabinet_id, op, payload, edited_at)
    SELECT lower(hex(randomblob(16))), 'packages', p.id, m.cabinet_id, 'insert', json_object('medicine_id', json(json_quote(p.medicine_id)), 'expires', json(json_quote(p.expires)), 'quantity', json(json_quote(p.quantity)), 'opened_at', json(json_quote(p.opened_at)), 'status', json(json_quote(p.status)), 'created_at', json(json_quote(p.created_at))), strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
    FROM packages p JOIN medicines m ON m.id = p.medicine_id WHERE m.cabinet_id = NEW.id ORDER BY p.created_at;
  INSERT INTO outbox (id, entity, entity_id, cabinet_id, op, payload, edited_at)
    SELECT lower(hex(randomblob(16))), 'medicine_categories', mc.medicine_id || '|' || mc.category, m.cabinet_id, 'insert', json_object('medicine_id', json(json_quote(mc.medicine_id)), 'category', json(json_quote(mc.category))), strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
    FROM medicine_categories mc JOIN medicines m ON m.id = mc.medicine_id WHERE m.cabinet_id = NEW.id;
END;
